import os
import numpy as np

# =============================================================================
# FILE SYSTEM PATHS
# =============================================================================
# Input directories
INPUT_DIR = "./input"
IMAGES_DIR = os.path.join(INPUT_DIR, "images")
METADATA_DIR = "./metadata"

# Metadata file paths (generated by previous steps)
TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

# Working directory for caching augmented features and intermediate artifacts
WORKING_DIR = "./working/idea_opt"
os.makedirs(WORKING_DIR, exist_ok=True)

# Submission directory and file
SUBMISSION_DIR = "./submission"
os.makedirs(SUBMISSION_DIR, exist_ok=True)
SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

# =============================================================================
# GLOBAL CONFIGURATION
# =============================================================================
RANDOM_STATE = 42
N_JOBS = 12  # Utilize all available vCPUs

# =============================================================================
# MODEL HYPERPARAMETERS
# =============================================================================

# 1. Logistic Regression (Used in Linear and Kernel branches)
# Broad logarithmic grid to capture both strong regularization and high complexity
# Range: 10^-3 to 10^4, 20 steps to cover stronger regularization if needed
LR_CS_GRID = np.logspace(-3, 4, 20)
LR_CV_FOLDS = 3
LR_SCORING = "neg_log_loss"
LR_SOLVER = "lbfgs"
LR_MAX_ITER = 5000  # Increased iteration limit for convergence

# 2. Linear Discriminant Analysis (Generative Branch)
# Using Ledoit-Wolf shrinkage ('auto') with Least Squares solver for stability
LDA_SOLVER = "lsqr"
LDA_SHRINKAGE = "auto"

# 3. Nystroem Kernel Approximation (Non-linear Branch)
# PCA settings to densify features before kernel mapping
PCA_VARIANCE = 0.95

# Nystroem settings to approximate RBF kernel
NYSTROEM_COMPONENTS = 400  # Number of kernel components
NYSTROEM_GAMMA = None  # None implies 1 / n_features

# =============================================================================
# FEATURE ENGINEERING
# =============================================================================
# List of explicit morphological descriptors to extract from binary images
MORPHOLOGICAL_FEATURES = ["aspect_ratio", "solidity", "extent", "eccentricity"]

# =============================================================================
# EVALUATION & SUBMISSION
# =============================================================================
# Clipping epsilon to avoid log(0) in metric calculation
CLIP_EPSILON = 1e-15
